def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    shift_count = 0

    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            shift_count = i
            break

    if shift_count == 0:
        return True

    for i in range(shift_count + 1, n):
        if arr[i] < arr[i - 1]:
            return False

    return arr[0] >= arr[-1]
